import re, itertools
samples = {}
files = ['incumbent_body.txt','best_83.lean','e1.lean','e2.lean','e3.lean','candB.lean','candA.lean']
target = {'incumbent_body.txt':348,'best_83.lean':83,'e1.lean':83,'e2.lean':85,'e3.lean':84,'candB.lean':81,'candA.lean':71}
def body(f):
    s=open(f).read()
    return s.split(':=',1)[1] if f.endswith('.lean') else s
B={f:body(f) for f in files}
cands = {
 'ws': r'\\S+',
 'wp': r\"\\w+|["'^'"\\w\\s]\",
 'wp2': r\"[\\w']+\",
 'dot_split': r\"[A-Za-z_][A-Za-z0-9_']*|\\d+|["'^'"\\w\\s\\d]\",
 'alnum_or_punct_run': r\"[A-Za-z0-9_]+|["'^A-Za-z0-9'"\\s]+\",
 'split_dot_ws': r\"["'^.'"\\s]+\",
 'punct_sep_ws': None,
}
for name,pat in cands.items():
    if pat is None: continue
    res={f: len(re.findall(pat, B[f], re.UNICODE)) for f in files if f in target}
    err=sum(abs(res[f]-target[f])/target[f] for f in res)/len(res)
    print(name, res, 'relerr %.3f'%err)
# custom: split on whitespace then split each word on dots keeping punctuation
def tok_x(t):
    n=0
    for w in t.split():
        # split off leading/trailing punctuation as separate tokens, and split identifiers on '.'
        parts=re.split(r'\\.', w)
        n+=sum(max(1,len(re.findall(r\"[A-Za-z0-9_'\\u00c0-\\uffff]+|.\",p))) if not re.fullmatch(r\"[A-Za-z0-9_'.]*\",p) else 1 for p in parts)
    return n
def tok_y(t):
    return sum(len(re.findall(r\"[A-Za-z_][A-Za-z0-9_']*|\\d+|.\", w)) for w in t.split())
for name,fn in [('x',tok_x),('y',tok_y)]:
    res={f: fn(B[f]) for f in files if f in target}
    err=sum(abs(res[f]-target[f])/target[f] for f in res)/len(res)
    print(name,res,'relerr %.3f'%err)
PY
